static void sc_asn1_print_object_id(const u8 * buf, size_t buflen)
{
        struct sc_object_id oid;
        const char *sbuf;

        if (sc_asn1_decode_object_id(buf, buflen, &oid)) {
                printf("decode error");
                return;
        }

        sbuf = sc_dump_oid(&oid);
        printf(" %s", sbuf);
        openssl_print_object_sn(sbuf);
}

sc_dump_oid(const struct sc_object_id *oid)
{
        static char dump_buf[SC_MAX_OBJECT_ID_OCTETS * 20];
        size_t ii;

        memset(dump_buf, 0, sizeof(dump_buf));
        if (oid)
                for (ii=0; ii<SC_MAX_OBJECT_ID_OCTETS && oid->value[ii] != -1; ii++)
                        snprintf(dump_buf + strlen(dump_buf), sizeof(dump_buf) - strlen(dump_buf), "%s%i", (ii ? "." : ""), oid->value[ii]);

        return dump_buf;
}

